// Placemaker — curated automatic pools (playtest 4b #2: "the benches are wrong, it's using the wrong
// decals, the wrong planter boxes, it just looks like a weird nightmare"). GPL-3.0.
//
// Name patterns alone let building extensions ("HighSchool03 Rooftop Garden" has a bench activity),
// raised garden beds (GardenBed01*), wall fountains, sofas, road-marking letters and "Ground Texture"
// decals ("text"!) into the automatic pools. This file holds the curation, checked against a real
// player's ModsData/Placemaker/catalog-dump.json (docs/ASSET-CURATION.md, regenerated by
// Tests/Placemaker.Tests/AssetCurationTests.cs):
//   • core categories: built-in (vanilla) prefabs are automatic ONLY when on an ordered allow-list
//     (order = preference; the first item is the category default);
//   • modded prefabs keep name-pattern fallbacks, minus known mismatches (planter boxes are not bushes,
//     tram/stadium/sport seats are not benches, wall/roof/driveway lights are not path lamps…);
//   • decals are themed by the LAST theme keyword in the name (modded packs prefix every item with the
//     pack name: "G87 Stains and Puddles Decals Wet Pack Stains G87 Stain A S Decal" is a stain), and
//     the park pools take natural decals only: no road markings, letters, numbers or texture tiles.

using System;
using System.Collections.Generic;

namespace Placemaker.Core.Build
{
    public static class AssetCuration
    {
        // ───────────────────────── vanilla allow-lists ─────────────────────────

        /// <summary>
        /// Ordered name prefixes of the built-in prefabs a player expects for each core category. A
        /// vanilla item of a listed category is automatic only when its name starts with one of these
        /// (and contains none of <see cref="VanillaExclusions"/>).
        /// </summary>
        public static readonly IReadOnlyDictionary<string, string[]> VanillaAllow = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            // Park benches (never OutdoorSofa, Chair, DeckChair, PierBench, SportParkBench, bus/taxi stops).
            [AssetCategories.Bench] = new[] { "GardenBench0", "Pack10-Bench0", "CampgroundBench0" },
            // Pedestrian-scale park lamp posts (never street/industrial/commercial poles, wall/roof/ground lights).
            [AssetCategories.Lamp] = new[] { "LightpolePark0", "EU_LightpolePark0", "NA_LightpolePark0" },
            [AssetCategories.Bin] = new[] { "Trashbin0" },
            // Free-standing shrubs (never GardenBed raised beds or the concrete-box "BushCity" planters).
            [AssetCategories.Bush] = new[]
            {
                "GreenBushWild0", "FlowerBushWild0", "GreenBushWildAdult", "GreenBushWildTeen", "FlowerBushWildElderly",
                "GreenBushWildElderly", "FlowerBushWildChild", "GreenBushWildChild",
            },
            // Temperate park trees first (variety picks among the first six); palms are explicit picks only.
            [AssetCategories.Tree] = new[]
            {
                "NA_LindenTree", "OakTree", "EU_ChestnutTree", "NA_LondonPlaneTree", "BirchTree", "EU_AlderTree",
                "NA_HickoryTree", "EU_PoplarTree", "AppleTree", "PineTree", "SpruceTree", "EuropeanSpruce",
            },
            // Planter = a plant in a container: boxed shrubs, pots, then raised garden beds.
            [AssetCategories.Planter] = new[] { "FlowerBushCity0", "GreenBushCity0", "FlowerPot0", "PlantPot0", "GardenBed0" },
            [AssetCategories.Flowerbed] = new[] { "Flowerbed0" },
            [AssetCategories.Hedge] = new[] { "HedgePiece" },
            // Free-standing fountains (WallFountain needs a wall; clock pointers are building parts).
            [AssetCategories.Centerpiece] = new[] { "SmallFountain0", "LargeFountain0" },
            [AssetCategories.CenterpieceFountain] = new[] { "SmallFountain0", "LargeFountain0" },
            [AssetCategories.Playground] = new[]
            {
                "PlaygroundPlayset0", "ClimbingFrame0", "SwingSet0", "Slide0", "Seesaw0", "Sandbox0", "PlaygroundMountain0",
            },
            // Picnic "tables": blankets (vanilla has no picnic table; grills are not tables).
            [AssetCategories.Picnic] = new[] { "PicnicBlanket0" },
            [AssetCategories.Restroom] = new[] { "Outhouse0", "PortableToilet0" },
            // Park kiosks (never pier kiosks, ticket machines, vending machines or market billboards).
            [AssetCategories.Kiosk] = new[] { "Kiosk0", "FoodCart0", "FoodStall0" },
            // Natural stones (Rock01..30); boulders join when the game allows them on land.
            [AssetCategories.Rock] = new[] { "Rock0", "Rock1", "Rock2", "Rock3", "Boulder0" },
            [AssetCategories.Bollard] = new[] { "Bollard0" },
            [AssetCategories.Shelter] = new[] { "Gazebo0", "Pergola0", "CampgroundShelter0" },
        };

        /// <summary>Words that exclude a vanilla item even when its prefix is allowed.</summary>
        private static readonly Dictionary<string, string[]> VanillaExclusions = new Dictionary<string, string[]>(StringComparer.Ordinal)
        {
            [AssetCategories.Bush] = new[] { "Dead" },
            [AssetCategories.Planter] = new[] { "Dead" },
        };

        /// <summary>Position of a vanilla prefab in its category's allow-list (-1 = not listed / not curated).</summary>
        public static int VanillaIndex(string category, string name)
        {
            if (category == null || string.IsNullOrEmpty(name) || !VanillaAllow.TryGetValue(category, out var list)) return -1;
            if (VanillaExclusions.TryGetValue(category, out var ex))
                foreach (var e in ex) if (name.IndexOf(e, StringComparison.Ordinal) >= 0) return -1;
            for (int i = 0; i < list.Length; i++)
                if (name.StartsWith(list[i], StringComparison.Ordinal)) return i;
            return -1;
        }

        public static bool IsCurated(string category) => category != null && VanillaAllow.ContainsKey(category);

        // ───────────────────────── automatic eligibility ─────────────────────────

        /// <summary>Modded mismatches per category (lower-case name parts).</summary>
        private static string[] ModdedExclusions(string category)
        {
            switch (category)
            {
                case AssetCategories.Bench:
                    return new[] { "planter", "table", "station", "tram", "bus", "stop", "sport", "stadium", "pier", "fake", "picnic", "sofa", "chair", "dugout" };
                case AssetCategories.Lamp:
                    return new[] { "wall", "roof", "tunnel", "driveway", "ground", "spot", "flood", "stadium", "industrial", "neon", "christmas", "festoon" };
                case AssetCategories.Bush:
                    return new[] { "city", "gardenbed", "garden bed", "dead", "pot", "box", "planter", "crop" };
                case AssetCategories.Planter:
                    return new[] { "depot", "garage", "storage", "dispatch", "extension", "dead" };
                case AssetCategories.Tree:
                    return new[] { "bush", "dead", "stump", "fallen", "illuminated" };
                case AssetCategories.Kiosk:
                case AssetCategories.MarketStall:
                    return new[] { "supermarket", "billboard", "poster", "sign", "screen", "vending", "ticket", "awning", "propane", "pylon" };
                case AssetCategories.Centerpiece:
                case AssetCategories.CenterpieceFountain:
                case AssetCategories.CenterpieceStatue:
                    return new[] { "wall", "clock", "pointer", "drinking" };
                case AssetCategories.Playground:
                    return new[] { "gate", "school", "dog" };
                case AssetCategories.Bin:
                    return new[] { "station", "container", "dumpster", "industrial" };
                case AssetCategories.Bollard:
                    return new[] { "mooring" };
                case AssetCategories.Picnic:
                    return new[] { "mcdonald" };
                default:
                    return Array.Empty<string>();
            }
        }

        /// <summary>
        /// Curated automatic eligibility of an object for a core category, or null when the category is
        /// not curated (other rules decide). Vanilla: allow-list only. Modded: no building extension or
        /// brand variant, none of the category's known mismatches.
        /// </summary>
        public static bool? AutoEligible(string category, string name, AssetTraits t)
        {
            if (!IsCurated(category) || string.IsNullOrEmpty(name)) return null;
            var lower = name.ToLowerInvariant();
            if ((t & AssetTraits.Vanilla) != 0) return VanillaIndex(category, name) >= 0;
            if (name.Contains(" - ")) return false;   // "Billboard01 - ShortMarket": brand variants
            if (AssetHeuristics.ContainsAny(lower, ModdedExclusions(category))) return false;
            switch (category)
            {
                case AssetCategories.Bench:
                    foreach (var w in AssetHeuristics.Words(name)) if (w == "bench" || w == "benches" || w == "bank" || w == "sitzbank" || w == "parkbank") return true;
                    return lower.Contains("bench");
                case AssetCategories.Planter:
                    return AssetHeuristics.ContainsAny(lower, "planter", "flowerpot", "flower pot", "plantpot", "plant pot", "potted", "plantbox", "plant box", "citybush", "bushcity", "city bush")
                           || HasWord(name, "pot", "pots", "box", "city");
                case AssetCategories.Flowerbed:
                    return AssetHeuristics.ContainsAny(lower, "flowerbed", "flower bed");
                case AssetCategories.Restroom:
                    return AssetHeuristics.IsRestroomName(name);
                case AssetCategories.Rock:
                    return !lower.Contains("cliff");
                default:
                    return null;   // generic name exclusions still apply
            }
        }

        /// <summary>Score bonus that keeps the allow-list order (vanilla) for the automatic default.</summary>
        public static int Score(string category, string name)
        {
            int i = VanillaIndex(category, name);
            return i < 0 ? 0 : 1000 - i * 20;
        }

        public static bool HasWord(string name, params string[] words)
        {
            foreach (var w in AssetHeuristics.Words(name))
                foreach (var x in words) if (w == x) return true;
            return false;
        }

        // ───────────────────────── decals ─────────────────────────

        private static readonly Dictionary<string, string> DecalWords = BuildDecalWords();

        private static Dictionary<string, string> BuildDecalWords()
        {
            var d = new Dictionary<string, string>(StringComparer.Ordinal);
            void Map(string theme, params string[] words) { foreach (var w in words) d[w] = theme; }
            Map(AssetCategories.DecalGraffiti, "graffiti", "graff", "mural", "murals");
            Map(AssetCategories.DecalLeaves, "leaf", "leaves", "foliage", "petal", "petals", "needles", "twig", "twigs", "acorns");
            Map(AssetCategories.DecalPuddles, "puddle", "puddles", "wet", "splash", "water");
            Map(AssetCategories.DecalLitter, "trash", "litter", "debris", "cardboard", "papers", "garbage", "rubbish", "glass");
            Map(AssetCategories.DecalDirt, "dirt", "dirty", "mud", "muddy", "dust", "dusty", "soil", "grime", "rust", "stain", "stains",
                "leak", "leakage", "oil", "sand", "gravel", "seaweed", "seashells", "seafoam", "earth");
            Map(AssetCategories.DecalCracks, "crack", "cracks", "cracked", "damage", "damaged", "pothole", "potholes", "patch", "patches", "tar");
            Map(AssetCategories.DecalPaving, "paving", "pavement", "pavements", "tile", "tiles", "brick", "bricks", "cobble", "cobbles",
                "cobblestone", "cobblestones", "sidewalk", "manhole", "drain", "grate", "pavers", "flagstone");
            Map(AssetCategories.DecalMarkings, "marking", "markings", "arrow", "arrows", "striping", "crosswalk", "zebra", "chevrons",
                "alphabet", "number", "letter", "text", "speed", "lane", "parking", "icon", "court", "grid", "playground");
            return d;
        }

        /// <summary>
        /// Theme sub-category of a decal (null = none; still in "decal"). The LAST theme word of the name
        /// wins, so pack prefixes do not decide ("…Wet Pack Stains G87 Stain A S" is dirt, "…Puddles G87
        /// Puddle Mirror 01" is a puddle). Whole words only: "Ground Texture" is not "text".
        /// </summary>
        public static string DecalTheme(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            var words = AssetHeuristics.Words(name);
            string theme = null;
            for (int i = 0; i < words.Count; i++)
            {
                var w = words[i];
                if (!DecalWords.TryGetValue(w, out var t))
                {
                    // Sports field outlines ("FootballFieldDecal01", "MultipurposeSportFieldDecal02").
                    if (w == "field" && i > 0 && (words[i - 1] == "football" || words[i - 1] == "sport")) theme = AssetCategories.DecalMarkings;
                    continue;
                }
                // "Grass Patch" / "Dirt Patch": worn ground, not a repaired crack.
                if (t == AssetCategories.DecalCracks && (w == "patch" || w == "patches") && i > 0 && (words[i - 1] == "grass" || words[i - 1] == "dirt"))
                    t = AssetCategories.DecalDirt;
                theme = t;
            }
            return theme;
        }

        private static readonly string[] DecalNeverAuto =
        {
            "random", "placeholder", "test", "chirper", "logo", "advert", "roundabout", "curb", "aerial", "wall", "roof", "building",
        };

        /// <summary>Per-theme exclusions (lower-case name parts) for the automatic decal pools.</summary>
        private static string[] DecalThemeExclusions(string category)
        {
            switch (category)
            {
                case AssetCategories.DecalLeaves: return new[] { "palm", "beach", "sea " };
                case AssetCategories.DecalDirt:
                    return new[] { "road", "beach", "sea", "tire", "track", "oil", "leak", "trash", "litter", "debris", "glass", "cardboard" };
                case AssetCategories.DecalLitter: return new[] { "sea", "beach" };
                case AssetCategories.DecalPuddles: return new[] { "curb", "drain", "track", "beach", "golden sand" };
                case AssetCategories.DecalPaving: return new[] { "roof", "wall", "curb", "thin", "thick", "manhole" };
                default: return Array.Empty<string>();
            }
        }

        /// <summary>Hard exclusions for marking pools: letters, numbers, text, speed limits and whole sports pitches never go automatic.</summary>
        private static bool IsTextOrPitchMarking(string name)
        {
            foreach (var w in AssetHeuristics.Words(name))
                switch (w)
                {
                    case "alphabet": case "number": case "letter": case "text": case "speed": case "bus": case "taxi": case "stop": case "slow":
                    case "only": case "wrong": case "court": case "field": case "football": case "basketball": case "tennis": case "sport":
                    case "playground": case "grid": case "container": case "ban": case "tracks":
                        return true;
                }
            return false;
        }

        /// <summary>Automatic eligibility of a decal (any decal.* category or "decal").</summary>
        public static bool DecalAutoEligible(string category, string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            var lower = name.ToLowerInvariant();
            if (AssetHeuristics.ContainsAny(lower, DecalNeverAuto)) return false;
            var theme = DecalTheme(name);
            if (category == AssetCategories.Decal)
            {
                // The general pool is a fallback for natural wear (ground patches, construction dirt):
                // natural themes only, never markings, graffiti, paving tiles or unthemed textures.
                if (theme != AssetCategories.DecalLeaves && theme != AssetCategories.DecalDirt) return false;
                return !AssetHeuristics.ContainsAny(lower, DecalThemeExclusions(theme));
            }
            if (theme != category) return false;
            if (category == AssetCategories.DecalMarkings) return !IsTextOrPitchMarking(name);
            return !AssetHeuristics.ContainsAny(lower, DecalThemeExclusions(category));
        }

        /// <summary>Preference inside a decal pool (higher first): subtle, scattered, natural looks.</summary>
        public static int DecalScore(string category, string name)
        {
            var lower = (name ?? "").ToLowerInvariant();
            int s = 0;
            switch (category == AssetCategories.Decal ? DecalTheme(name) : category)
            {
                case AssetCategories.DecalLeaves:
                    if (lower.Contains("scattered")) s += 40;
                    if (lower.Contains("light")) s += 30;
                    if (lower.Contains("medium")) s += 15;
                    if (lower.Contains("lined")) s -= 40;
                    if (lower.Contains("trash")) s -= 20;
                    break;
                case AssetCategories.DecalDirt:
                    if (lower.Contains("ground")) s += 30;
                    if (HasWord(name, "dirt", "soil", "mud", "earth")) s += 20;
                    if (lower.Contains("terrain") || lower.Contains("path")) s += 10;
                    if (HasWord(name, "stain", "stains", "rust", "grime")) s -= 15;
                    if (lower.Contains("sand")) s -= 10;
                    break;
                case AssetCategories.DecalCracks:
                    if (HasWord(name, "crack", "cracks", "cracked")) s += 40;
                    if (lower.Contains("small")) s += 10;
                    if (HasWord(name, "damage", "damaged")) s += 5;
                    if (HasWord(name, "patch", "patches", "asphalt")) s -= 15;
                    break;
                case AssetCategories.DecalPuddles:
                    if (HasWord(name, "puddle", "puddles")) s += 40;
                    if (lower.Contains("grass")) s += 15;
                    if (lower.Contains("sand")) s -= 20;
                    if (lower.Contains("splash")) s -= 10;
                    break;
                case AssetCategories.DecalPaving:
                    if (HasWord(name, "tiles", "tile", "cobble", "cobblestone", "pavers")) s += 30;
                    if (lower.Contains("garden") || lower.Contains("stone")) s += 20;
                    if (lower.Contains("sidewalk")) s -= 20;
                    break;
                case AssetCategories.DecalMarkings:
                    if (lower.Contains("striping")) s += 30;
                    if (lower.Contains("arrow")) s += 10;
                    break;
            }
            return s;
        }

        // ───────────────────────── palettes ─────────────────────────

        /// <summary>
        /// A vanilla park palette suitable for dressing an ordinary park: a park/garden/plaza/playground
        /// asset that is not a themed facility. Sports grounds, campfire sites, landmarks, hotels and
        /// overpasses brought floodlights, campground benches and driveway lights into ordinary parks.
        /// </summary>
        public static bool IsGeneralParkPalette(string paletteOrParkName)
        {
            if (string.IsNullOrEmpty(paletteOrParkName)) return false;
            var lower = paletteOrParkName.ToLowerInvariant();
            if (!AssetHeuristics.ContainsAny(lower, "park", "garden", "plaza", "playground")) return false;
            return !AssetHeuristics.ContainsAny(lower, "sport", "skate", "dog", "gym", "water", "school", "university", "college",
                "stadium", "arena", "zoo", "farm", "cemetery", "golf", "beach", "marina", "harbor", "harbour", "landmark",
                "football", "basketball", "baseball", "tennis", "bicycle", "bike", "pool", "campfire", "camp", "ruins", "theatre",
                "theater", "parking", "overpass", "hotel", "castle", "museum", "statue", "tower", "ferris", "maintenance", "depot");
        }
    }
}
